
import React, { useState, useEffect } from "react";


import "../component/dashboard.css"
import "../component/styles.css"
import {  TextInput_Cmpt, TimePickerDrop_Cmpt, CheckBoxSlide_Cmpt, TimePickerWrapper_Cmpt, DropDwnPicker_Cmpt} from "../../../components";
import {  gen16CodeId,  getStore, updStore, ObjectKeys } from "../../../stores/Utils";
import { CloseModal } from "../../../components/DialogHRM";

import { GrayButton } from "../../../components/Buttons";


const TextInput = TextInput_Cmpt();

// const TimePickerDrop = TimePickerDrop_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const DropDwnPicker = DropDwnPicker_Cmpt();


const DimensionModal  = ({
	data,
	requiredHeight,
	holdWidth,
	vertice,
	cDm,
	confirm,
	type,
	profile
 }) => {


	const frmNm = "verticeUpdFrm_"+type +"_"+vertice;

	const [, set_obs] = useState(1);


	useEffect(() => {
		let loadFrm = cDm || {vertice};
		console.log(loadFrm)
		updStore(frmNm, loadFrm);
		set_obs(gen16CodeId())
	},[vertice]);


	const closeDetails = (f,v) => {
		let frm2 = getStore(frmNm);
		frm2.profile = frm2.needProfile? profile: null;

		confirm(frm2);
		updStore(frmNm, null);
		close();
	}


	const close  = ()  => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		frm2[f] = v;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};



	


	
    return (
		<div style={{
			maxHeight: "86vh",
			minHeight: "65vh",
			width: "560px",
			overflow: "auto",
			background: "var(--dark-700)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					{`Dimension para el ${requiredHeight?"" :"vertice"} ${vertice}`}
				</p>
			</div>

			<div className="centerBx" style={{margin: "19px auto"}}>
					
				<div className="flexSpace"/> 
					<span className={`checklabel`}>
						{"Need Profile"}
					</span>
					
					<CheckBoxSlide
						initvalue={getStore(frmNm)?.["needProfile"]?true:false}
						keyCode={89}
						updChange={(e)=>updFrm("needProfile",e*1)}
						color={"var(--primary-blue--backg-30)"}
					/>
				<div className="flexSpace"/>
				{requiredHeight? null : 
				<div className="_dsplFlx " style={{margin:"19px auto"}}>
					
					<span className={`checklabel`}>
						{"Is in Wall"}
					</span>
					
					<CheckBoxSlide
						initvalue={getStore(frmNm)?.["isWall"]?true:false}
						keyCode={89}
						updChange={(e)=>updFrm("isWall",e*1)}
						color={"var(--primary-blue--backg-30)"}
					/>
					
				</div>}
				<div className="flexSpace"/>
			</div>
			{holdWidth? null:
			<div className="_dsplFlx spaceAround flxWrp" style={{margin:"19px auto"}}> 
				
				<TextInput 
					init={getStore(frmNm)?.["width"]} 
					label={"Largo (in)"} 
					width={140} 
					updChanges={(e)=>updFrm("width",e*1)}
					type={"number"}
				/>
				
				{requiredHeight?
					<TextInput 
						init={getStore(frmNm)?.["height"]} 
						label={"Ancho (in)"} 
						width={140} 
						updChanges={(e)=>updFrm("height",e*1)}
						type={"number"}
					/>
				:null}
			</div>}
			
			{holdWidth? null:
			<div className="_dsplFlx spaceAround flxWrp" style={{margin:"19px auto"}}> 
				<TextInput 
					init={getStore(frmNm)?.["xPos"]}
					label={"X Position"} 
					width={180} 
					updChanges={(e)=>updFrm("xPos",e*1)}
					type={"number"}
				/>
				<TextInput 
					init={getStore(frmNm)?.["yPos"]}
					label={"Y Position"} 
					width={180} 
					updChanges={(e)=>updFrm("yPos",e)}
					type={"number"}
				/>
			</div>
			}
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<div className="card">
						<GrayButton color={"#007bfc"} label={"Agregar"} clickHandler={closeDetails}/>
					
				</div>
			</div>


		</div>

    )   
}



export default DimensionModal;



const isValidB  = (advanceFilters, frm2)  => {
	let vld = 0;
	ObjectKeys(advanceFilters).map(ffa=>{
		let sft = frm2?.start || 0;
		let eft = frm2?.end || 0;
		let st = ffa.split("_")[0];
		let et = ffa.split("_")[1];
		if((sft >= st && sft <= et) || (eft >= st && eft <= et) ){
			vld = 1;
		}
	})
	return !vld && frm2?.minimunPay && frm2?.minimunPayByHour;
}



