export const LShapeCardItem  = ({dmz, handleLines}) => {


	
	let mg = 6;
    let X1 = 600;
    let X2 = 300;
    let YL3 = 300;
	let YL4 = 120;
	


    let SNK1 = 250;
	let SNK2 = 200;
	let SNKX = 250;
	let SNKY = 250;


	
	let testPurple = "#FE7817";
	let testOrange = "#902ef2";
	let frameDashColor = "#2c2c2c";


	const handleM = (v) =>{
		console.log(v);
	}

	return (
		
		
		<>
			
				{/********** 1 back line on Wall *********/}
				<line x1={dmz?.x} y1={dmz?.y} x2={dmz?.x+X1+mg}  y2={dmz?.y} className={"dashline1"} stroke={frameDashColor} strokeDasharray="0 3 0" onClick={()=>handleM(1)}/>
				<line x1={dmz?.x+mg} y1={dmz?.y+mg} x2={dmz?.x+X1}  y2={dmz?.y+mg}  stroke="#bdbdbd" />
			
				{/********** 2 front line on left side *********/}
				<line x1={dmz?.x} y1={dmz?.y+YL3+mg} x2={dmz?.x+X2-mg} className={"dashline2"}  y2={dmz?.y+YL3+mg}  stroke={frameDashColor} strokeDasharray="0 3 0" onClick={()=>handleM(2)}/>
				<line x1={dmz?.x+mg} y1={dmz?.y+YL3} x2={dmz?.x+X2}  y2={dmz?.y+YL3}   stroke="#bdbdbd"/>
			
				{/********** 3 font line left side *********/}
				<line x1={dmz?.x} y1={dmz?.y} x2={dmz?.x}  y2={dmz?.y+YL3+mg}  className={"dashline3"} stroke={frameDashColor} strokeDasharray="0 3 0" onClick={()=>handleM(3)}/>
				<line x1={dmz?.x+mg} y1={dmz?.y+mg} x2={dmz?.x+mg}  y2={dmz?.y+YL3} stroke="#bdbdbd" />
		
				{/********** 4 font line left side *********/}
				<line x1={dmz?.x+X2-mg } y1={dmz?.y+YL3+mg} x2={dmz?.x+X2-mg}  className={"dashline4"} y2={dmz?.y+YL3+YL4+mg}  stroke={frameDashColor} strokeDasharray="0 3 0" onClick={()=>handleM(4)}/>
				<line x1={dmz?.x+X2} y1={dmz?.y+YL3} x2={dmz?.x+X2}  y2={dmz?.y+YL3+YL4} stroke="#bdbdbd" />
			
				{/********** 5 front line on right side *********/}
				<line x1={dmz?.x+X2-mg} y1={dmz?.y+YL3+mg+YL4} x2={dmz?.x+X1+mg}  className={"dashline5"} y2={dmz?.y+YL3+mg+YL4}  stroke={frameDashColor} strokeDasharray="0 3 0" onClick={()=>handleM(5)}/>
				<line x1={dmz?.x+X2} y1={dmz?.y+YL3+YL4} x2={dmz?.x+X1}  y2={dmz?.y+YL3+YL4}   stroke="#bdbdbd"/>
			
				{/********** 6 font line Right side *********/}
				<line x1={dmz?.x+X1+mg } y1={dmz?.y} x2={dmz?.x+X1+mg}  y2={dmz?.y+YL3+YL4+mg}  stroke={frameDashColor} strokeDasharray="0 3 0"  className={"dashline6"} onClick={()=>handleM(6)}/>
				<line x1={dmz?.x+X1} y1={dmz?.y+mg} x2={dmz?.x+X1}  y2={dmz?.y+YL3+YL4} stroke="#bdbdbd" />


		</>
	)
}














