export const UShapeScketch  = ({wT, hT, svDm, addBlPr, profile, item , disable }) => {
	const [, set_obs] = useState(1);
	const [scale, setScale] = useState(5);
	const [hasSink, setHasSink] = useState(false);

	const imgDiv = useRef(null);
	let wwT = wT || 750;
	let hhT =  hT || 500;

	let shape = "U_Shape";

	const refreshAccs =  (v) => {
		
		let cDm2 = getStore("bluePrint") || svDm;
		if(!cDm2){
			cDm2 = {}
			cDm2["type"] = "U";
			cDm2["vertices"] = {}
		}
		v.profile = v.needProfile? profile: null;
		cDm2["vertices"][v.vertice] = v;
		
		updStore("bluePrint",cDm2)
		set_obs(gen16CodeId());
	}



	let cDm = getStore("bluePrint")?.["vertices"] || svDm?.["vertices"] || {};

	const handleLines =  (v, hW, rH) => {
		if(!disable){
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			modaldata["content"] = 
				<DimensionModal 
					confirm={refreshAccs} 
					vertice={v}
					holdWidth={hW}
					requiredHeight={rH}
					profile={profile}
					cDm={cDm?.[v] || {vertice:v}}
				/>
			OpenModal(modaldata);
		}
	}


	const download =  () => {
		
		  htmlToImage.toPng(imgDiv.current)
			.then(function (dataUrl) {
				var img = new Image();
				img.src = dataUrl;
				console.log(dataUrl)	
				window.open(dataUrl)
				//document.body.appendChild(img);
			})
			.catch(function (error) {
				console.error('oops, something went wrong!', error);
			});
	}


	const save2Prod =  () => {
		if(!disable){
			addBlPr(getStore("bluePrint"));
		}
	}

	const remove =  () => {
		
	}
	
	return (
		<div className="xMid2Mid">
			<div className="_dsplFlx ">
				<div className="flexSpace" />
				<div className="clGojg iSTOvb kvXcCL "  style={{padding: 9 }} >
						Scketch U Shape
				</div>
				<div className="flexSpace" />
				<div className="_dsplFlx " >
					
					{cDm["sink"]?.width? null: 
					<div className="card">
						<GrayButton color={"#007bfc"} label={"Agregar Sink"} clickHandler={()=>handleLines("sink",0,1)}/>
					
					</div>
					}
				</div>
				
				<div className="flexSpace" />
				<TextInput 
					init={scale}
					label={"Scale"} 
					width={80} 
					updChanges={setScale}
					type={"number"}
				/>
				<div className="flexSpace" />
				<div className="card">
					{!disable?
						<GrayButton color={"#007bfc"} label={"Guardar"} clickHandler={save2Prod}/>
					:null}
				</div>
				<div className="icon align_itm" onClick={remove}>
				{!disable?
					<Svg name={"outline_delete"} color={"#F7251A"}/>
					:null}
				</div>
			</div>
		<div id={item.productId +"_"+ item?.bluePrint?.type } ref={imgDiv}
		style={{ width:wwT, height:hhT, position:"relative" }}>
			<UShapeCardItem 
				dmz={{
					x: 50,
					y: 30
				}} 
				handleLines={
					handleLines
				}
				cDm={cDm}
				scale={scale}
				hasSink={hasSink}
			/>
		</div>
		</div>
	)
}



export const UShapeCardItem  = ({dmz, handleLines, cDm, scale}) => {


	
	let mg = 6 ;
    let X1 = (cDm[1]?.width || 90) * scale;
    let X2 = (cDm[2]?.width || 30) * scale;
    let YL3 = (cDm[3]?.width || 50) * scale;
	let YL4 = (cDm[4]?.width || 24) * scale;
	let YL7 = (cDm[7]?.width || 20) * scale;
	let X8 = (cDm[8]?.width || 20) * scale;
	
	let X1Lbl = X1 / scale;
	let X2Lbl =  X2 / scale;
	let YL3Lbl =  YL3 / scale;
	let YL4Lbl =  YL4 / scale;
	let X8Lbl =  X8 / scale;

    let SNK1 = 250* scale;
	let SNK2 = 200* scale;
	let SNKX = 250* scale;
	let SNKY = 250* scale;



	if(cDm["sink"]?.width){
		SNK1 = cDm["sink"]?.width * scale;
		SNK2 = cDm["sink"]?.height * scale;
		SNKX = cDm["sink"]?.xPos* scale;
		SNKY = cDm["sink"]?.yPos* scale;
	}

	let testPurple = "#FE7817";
	let testOrange = "#902ef2";
	let frameColor = "#000";
	let frameDashColor = "#2c2c2c";

	const fillLine = (ve) => {
		return cDm[ve]?.profile ? <div className={"wall"}> { `${ cDm[ve]?.profile } ` } </div> : cDm[ve]?.isWall ?<div className={"wall"}> Wall </div> : null;
	}

	const fillLineByOb = (ve) => {
		//let cmp =  ve?.profile ? <div className={"wall"}> { ve?.profile }</div> : ve?.isWall ?<div className={"wall"}> Wall </div> : null;
		return ve?.profile ? ve?.profile : ve?.isWall ?ve?.isWall : "";
	}

	return (
		
		
		<>

				{/********** 1 back line on Wall *********/}
				<DrawLineX x1={dmz?.x} y1={dmz?.y} x2={dmz?.x+X1+mg}  y2={dmz?.y} color={frameDashColor} handleM={()=>handleLines(1)} hover={1}/>
				<DrawLineX x1={dmz?.x+mg} y1={dmz?.y+mg} x2={dmz?.x+X1}  y2={dmz?.y+mg}  color={frameColor} />
				<DrawLineText x1={dmz?.x+X1 / 2} y1={dmz?.y-mg*3.2} txt={X1Lbl.toFixed(2)} />
				<DrawLineText x1={dmz?.x+X1 / 2} y1={dmz?.y-mg*3.2 -12} cmp={fillLine(1)} />
				

				{/********** 2 front line on left side *********/}
				<DrawLineX x1={dmz?.x} y1={dmz?.y+YL3+mg} x2={dmz?.x+X2+mg}  y2={dmz?.y+YL3+mg} color={frameDashColor} handleM={()=>handleLines(2)} hover={1}/>
				<DrawLineX x1={dmz?.x+mg} y1={dmz?.y+YL3} x2={dmz?.x+X2}  y2={dmz?.y+YL3}   color={frameColor}/>
				<DrawLineText x1={dmz?.x+X2/2 } y1={dmz?.y+YL3+mg} txt={X2Lbl.toFixed(2) } />
				<DrawLineText x1={dmz?.x+X2/2 } y1={dmz?.y+YL3 + mg+ 12} cmp={fillLine(2)} />
				

				{/********** 3 font line left side *********/}
				<DrawLineY x1={dmz?.x} y1={dmz?.y}   y2={dmz?.y+YL3+mg}   color={frameDashColor}  handleM={()=>handleLines(3)} hover={1}/>
				<DrawLineY x1={dmz?.x+mg} y1={dmz?.y+mg}   y2={dmz?.y+YL3} color={frameColor} />
				<DrawLineText x1={dmz?.x - mg*5} y1={dmz?.y+(YL3)/2} txt={YL3Lbl.toFixed(2)} />
				<DrawLineText x1={dmz?.x - mg*5} y1={dmz?.y+(YL3)/2 + 12} cmp={fillLine(3)} />




				{/********** 5 front line on right side *********/}
				<DrawLineX x1={dmz?.x+mg+X2} y1={dmz?.y+YL3+mg-YL4} x2={dmz?.x+(X1-X8)-mg}  y2={dmz?.y+YL3+mg}  color={frameDashColor}  hover={1} handleM={()=>handleLines(5, 1)}/>
				<DrawLineX x1={dmz?.x+X2} y1={dmz?.y+YL3-YL4} x2={dmz?.x+(X1-X8)}  y2={dmz?.y+YL3} color={frameColor}/>
				<DrawLineText x1={dmz?.x + (X1 -X2 +  X8) /2} y1={dmz?.y+(YL3-YL4)+mg} txt={(X1Lbl - X2Lbl - X8Lbl).toFixed(2)} />
				<DrawLineText x1={dmz?.x + (X1 - X2 + X8) /2} y1={dmz?.y+(YL3-YL4) +mg+ 12} cmp={fillLine(5)} />
				

			


				{/********** 4 font line left side *********/}
				<DrawLineY x1={dmz?.x+X2+mg } y1={dmz?.y+YL3+mg-YL4} x2={dmz?.x+X2+mg}  y2={dmz?.y+YL3+mg}  color={frameDashColor}  hover={1} handleM={()=>handleLines(4)}/>
				<DrawLineY x1={dmz?.x+X2} y1={dmz?.y+YL3-YL4} x2={dmz?.x+X2}  y2={dmz?.y+YL3} color={frameColor} />
				<DrawLineText x1={dmz?.x +X2 + mg*2} y1={dmz?.y+YL3-YL4/2} txt={YL4Lbl.toFixed(2)} />
				<DrawLineText x1={dmz?.x +X2 + mg*2} y1={dmz?.y+YL3-YL4/2 + 12} cmp={fillLine(4)} />



				{/********** 6 font line Right side *********/}
				<DrawLineY x1={dmz?.x+X1+mg } y1={dmz?.y+mg } x2={dmz?.x+X1+mg}  y2={dmz?.y+YL3+mg}  color={frameDashColor}  handleM={()=>handleLines(6,1)} hover={1}/>
				<DrawLineY x1={dmz?.x+X1} y1={dmz?.y+mg} x2={dmz?.x+X1}  y2={dmz?.y+YL3} color={frameColor} />
				
				<DrawLineText x1={dmz?.x +X1 + mg*2} y1={dmz?.y+(YL3)/2} txt={(YL3Lbl*1).toFixed(2)} />
				<DrawLineText x1={dmz?.x +X1 + mg*2} y1={dmz?.y+(YL3)/2 + 12} cmp={fillLine(6)} />


				
			
				{/********** 7 font line left side *********/}
				
				<DrawLineY x1={dmz?.x+(X1-X8)-mg } y1={dmz?.y+YL3+mg-YL4} x2={dmz?.x+(X1-X8)-mg}  y2={dmz?.y+YL3+mg}  color={frameDashColor}  hover={1} handleM={()=>handleLines(7,1)}/>
				<DrawLineY x1={dmz?.x+(X1-X8)} y1={dmz?.y+YL3-YL4} x2={dmz?.x+(X1-X8)}  y2={dmz?.y+YL3} color={frameColor} />
				<DrawLineText x1={dmz?.x +(X1-X8) - mg*6} y1={dmz?.y+YL3-YL4/2} txt={YL4Lbl.toFixed(2)} />
				<DrawLineText x1={dmz?.x +(X1-X8) - mg*6} y1={dmz?.y+YL3-YL4/2 + 12} cmp={fillLine(4)} />



				{/********** 8 front line on right side *********/}
				<DrawLineX x1={dmz?.x+(X1-X8)-mg} y1={dmz?.y+YL3+mg} x2={dmz?.x+X1+mg} color={frameDashColor}  hover={1} handleM={()=>handleLines(8)}/>
				<DrawLineX x1={dmz?.x+(X1-X8)} y1={dmz?.y+YL3} x2={dmz?.x+X1} color={frameColor}/>
				<DrawLineText x1={dmz?.x+(X1-X8)-mg+45} y1={dmz?.y+YL3+mg} txt={(X8Lbl).toFixed(2)} />
				<DrawLineText x1={dmz?.x+(X1-X8)-mg+45} y1={dmz?.y+YL3+mg+12} cmp={fillLine(8)} />
				



				{/********** Sink line Right side *********/}
				{cDm["sink"]?.width? 
				<>
					<DrawRect x1={dmz?.x+SNKX } y1={dmz?.y+ SNKY} w={SNK1}  h={SNK2}  color="#4b4b4b" hover={1}  handleM={()=>handleLines("sink",0,1)}/>
					<DrawLineX x1={dmz?.x} y1={dmz?.y+SNKY} x2={dmz?.x+SNKX}  y2={dmz?.y+SNKY}  color={frameDashColor}  hover={1}/>
					<DrawLineY x1={dmz?.x+SNKX} y1={dmz?.y} x2={dmz?.x+SNKX}  y2={dmz?.y+SNKY}  color={frameDashColor}  hover={1}/>
					
					<DrawLineText x1={dmz?.x+SNKX/2} y1={dmz?.y+(SNKY)} txt={(cDm["sink"]?.xPos*1).toFixed(2)} />
					<DrawLineText x1={dmz?.x+SNKX+6} y1={dmz?.y+SNKY/2 -6} txt={(cDm["sink"]?.yPos*1).toFixed(2)} />

					<DrawLineText x1={dmz?.x+SNKX+SNK1/2 - SNK1/4} y1={dmz?.y+SNKY} txt={cDm["sink"]?.width.toFixed(2) + " - " + fillLineByOb(cDm["sink"]) }  />
					<DrawLineText x1={dmz?.x+SNKX + 6} y1={dmz?.y+SNKY + SNK2/2 } txt={ cDm["sink"]?.height.toFixed(2) + " - " + fillLineByOb(cDm["sink"]) }  />
				</>
				:null}

				
		</>
	)
}






















